#include "feature_extractor.hpp"
#include "kseed_codec.hpp"
#include "ledger.hpp"
#include "pipeline.hpp"
#include "seed.hpp"
#include "sha256.hpp"
#include <algorithm>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
using namespace ugts41;
namespace {EventProposal lifecycle(std::uint64_t seed,EventKind kind,std::uint64_t ordinal,std::uint64_t ts){EventProposal p;p.proposal_id=stable_id(seed,0x4c4946454359434cULL,ordinal);p.kind=kind;p.timestamp_ns=ts;p.stable_id=p.proposal_id;p.spatial_key=ordinal;p.confidence=1;p.numeric_error=0;p.uncertainty=0;p.guard=GuardStatus::Confirmed;p.support_ok=p.compatibility_ok=true;return p;}void commit(SpatialLedger&l,KseedWriter&w,const EventProposal&p){if(auto e=l.commit(p))w.append_event(*e);}}
int main(int argc,char**argv){const std::filesystem::path out=argc>1?argv[1]:".";std::filesystem::create_directories(out);const std::uint64_t seed=0x4b43534545443431ULL,start=1'700'000'000'000'000'000ULL;KseedHeader h;h.session_seed=seed;h.start_time_ns=start;h.analysis_width=160;h.analysis_height=90;h.capture_fps_x100=3000;h.feature_budget=96;h.profile_hash=sha256(std::span<const std::uint8_t>(reinterpret_cast<const std::uint8_t*>("poco_x7_pro_12gb_seed"),23));h.calibration_hash=sha256(std::span<const std::uint8_t>(reinterpret_cast<const std::uint8_t*>("demo_uncalibrated"),17));const auto path=out/"demo_session.kseed";KseedWriter writer(path,h,32U*1024U);if(!writer.good()){std::cerr<<writer.error()<<"\n";return 1;}SpatialLedger ledger(ProposalVerifier{VerificationPolicy{.35f,.03f,5.0f,false,false}});commit(ledger,writer,lifecycle(seed,EventKind::SessionStart,1,start));const auto world=generate_demo_world(seed,12);for(const auto&p:demo_world_proposals(world,seed,start+1'000'000,true))commit(ledger,writer,p);SeededFeatureExtractor extractor(seed,{160,90,16,9,96,13});KeyframeSelector selector({700'000'000ULL,120'000'000ULL,7,.07f,16});SessionStats stats;stats.session_seed=seed;stats.start_time_ns=start;std::vector<std::uint8_t> image(320U*180U);for(std::uint32_t frame=1;frame<=300;++frame){for(std::uint32_t y=0;y<180;++y)for(std::uint32_t x=0;x<320;++x){const auto noise=splitmix64(seed^std::uint64_t((x/12U)+(y/12U)*32U));const int wave=int(38.0*std::sin((x+frame*2U)*.045)+28.0*std::cos((y-frame)*.067));const int obstacle=(frame>150&&x>190&&x<245&&y>65&&y<145)?75:0;image[std::size_t(y)*320+x]=std::uint8_t(std::clamp(105+wave+int(noise&31U)+obstacle,0,255));}ImuSample imu;const float a=frame*.0015f;imu.orientation={0,std::sin(a/2),0,std::cos(a/2)};imu.angular_velocity={0,.045f,0};const auto timestamp=start+std::uint64_t(frame)*33'333'333ULL;auto extracted=extractor.extract(image.data(),320,180,320,1,frame,timestamp,imu);++stats.frames_seen;stats.raw_input_bytes+=image.size();if(selector.should_store(extracted.observation)){++stats.keyframes_stored;writer.append_frame(extracted.observation);for(const auto&p:proposals_from_frame(extracted.observation,seed,{8,.35f,1.0f})){++stats.proposals_seen;if(auto e=ledger.commit(p)){writer.append_event(*e);++stats.events_committed;}else ++stats.rejected_proposals;}}}commit(ledger,writer,lifecycle(seed,EventKind::SessionEnd,2,start+10'100'000'000ULL));stats.events_committed=ledger.events().size();stats.end_time_ns=start+10'100'000'000ULL;writer.close(stats);const auto read=read_kseed(path);if(!read.complete||!read.header_crc_ok||!read.chunk_crc_ok||!read.chain_ok){std::cerr<<"demo verification failed: "<<read.error<<"\n";return 2;}const auto stored=std::filesystem::file_size(path);const double ratio=stored?double(stats.raw_input_bytes)/stored:0.0;std::ofstream summary(out/"demo_session_summary.json");summary<<std::fixed<<std::setprecision(2)<<"{\n  \"schema\": \"ugts-kc-demo-summary-4.1\",\n  \"session_seed\": \"0x4b43534545443431\",\n  \"frames_seen\": "<<stats.frames_seen<<",\n  \"keyframes_stored\": "<<stats.keyframes_stored<<",\n  \"events_committed\": "<<ledger.events().size()<<",\n  \"raw_luma_bytes\": "<<stats.raw_input_bytes<<",\n  \"kseed_bytes\": "<<stored<<",\n  \"raw_to_kseed_ratio\": "<<ratio<<",\n  \"integrity_verified\": true,\n  \"state_hash\": \""<<hex_bytes(ledger.state_hash())<<"\",\n  \"scope\": \"synthetic deterministic host fixture, not a phone benchmark\"\n}\n";std::ofstream geo(out/"demo_route.geojson");geo<<"{\"type\":\"FeatureCollection\",\"features\":[";bool first=true;for(const auto&e:world.edges){auto a=std::find_if(world.nodes.begin(),world.nodes.end(),[&](const RouteNode&n){return n.id==e.from;});auto b=std::find_if(world.nodes.begin(),world.nodes.end(),[&](const RouteNode&n){return n.id==e.to;});if(a==world.nodes.end()||b==world.nodes.end())continue;if(!first)geo<<',';first=false;geo<<"{\"type\":\"Feature\",\"properties\":{\"id\":\""<<e.id<<"\",\"passable\":"<<(e.passable?"true":"false")<<"},\"geometry\":{\"type\":\"LineString\",\"coordinates\":[["<<a->position.x<<','<<a->position.z<<"],["<<b->position.x<<','<<b->position.z<<"]]}}";}geo<<"]}\n";std::cout<<"demo=\""<<path<<"\" bytes="<<stored<<" raw_ratio="<<ratio<<" keyframes="<<stats.keyframes_stored<<" events="<<ledger.events().size()<<"\n";return 0;}
